"""Dependency-free deterministic PDF 1.4 generation for plain-text documents.

The writer intentionally supports one Helvetica column, ASCII text, simple word
wrap and page breaks. It does not support images, embedded fonts, rich layouts,
signatures or non-Latin scripts.
"""

from __future__ import annotations

import unicodedata
from datetime import date, datetime

# Fixed PDF 1.4 timestamp: generated bytes depend only on their content.
PDF_CREATION_DATE = "D:20260101000000Z"
PAGE_WIDTH = 612
PAGE_HEIGHT = 792
MARGIN_X = 54
MARGIN_Y = 54
BODY_SIZE = 10
BODY_LEADING = 15
TITLE_SIZE = 17
MAX_LINE_WIDTH = PAGE_WIDTH - 2 * MARGIN_X
LINES_PER_PAGE = 44

_ASCII_REPLACEMENTS = str.maketrans({
    "₹": "Rs.",
    "‘": "'",
    "’": "'",
    "“": '"',
    "”": '"',
    "–": "-",
    "—": "-",
    "•": "*",
    "…": "...",
})


def ascii_text(value: object) -> str:
    """Convert merge values to a conservative printable ASCII representation."""

    text = str(value if value is not None else "").translate(_ASCII_REPLACEMENTS)
    normalized = unicodedata.normalize("NFKD", text)
    return "".join(char for char in normalized if 32 <= ord(char) <= 126)


def indian_grouping(value: int) -> str:
    """Group a whole number as 1,23,45,678 without locale dependence."""

    digits = str(abs(value))
    if len(digits) <= 3:
        grouped = digits
    else:
        rest = digits[:-3]
        groups: list[str] = []
        while len(rest) > 2:
            groups.insert(0, rest[-2:])
            rest = rest[:-2]
        if rest:
            groups.insert(0, rest)
        grouped = ",".join([*groups, digits[-3:]])
    return f"-{grouped}" if value < 0 else grouped


def format_money(paise: int) -> str:
    """Format integer paise as Indian-grouped rupees with two decimal places."""

    sign = "-" if paise < 0 else ""
    absolute = abs(paise)
    return f"{sign}Rs. {indian_grouping(absolute // 100)}.{absolute % 100:02d}"


def format_date(value: date | datetime | str) -> str:
    """Render dates consistently for artifacts and snapshots."""

    if isinstance(value, (date, datetime)):
        return value.strftime("%d %b %Y")
    return ascii_text(value)


def _char_width(char: str, size: int) -> float:
    # Conservative approximation for Helvetica. Only wrapping depends on this;
    # PDF viewers still use the standard font metrics when displaying glyphs.
    narrow = "iljI.,'!|:;()[]{} "
    wide = "mwMW@"
    factor = 0.28 if char in narrow else 0.65 if char in wide else 0.53
    return factor * size


def wrap_text(text: str, *, size: int = BODY_SIZE, width: int = MAX_LINE_WIDTH) -> list[str]:
    """Wrap on spaces without splitting ordinary words; hard-break overlong tokens."""

    lines: list[str] = []
    for paragraph in text.splitlines() or [""]:
        current = ""
        for word in paragraph.split(" "):
            piece = word
            # A single token wider than the column is split at character level.
            while _text_width(piece, size) > width:
                cut = 1
                while cut < len(piece) and _text_width(piece[:cut + 1], size) <= width:
                    cut += 1
                if current:
                    lines.append(current)
                    current = ""
                lines.append(piece[:cut])
                piece = piece[cut:]
            candidate = f"{current} {piece}" if current else piece
            if _text_width(candidate, size) <= width:
                current = candidate
            else:
                lines.append(current)
                current = piece
        lines.append(current)
    return lines


def _text_width(text: str, size: int) -> float:
    return sum(_char_width(char, size) for char in text)


def escape_pdf_text(text: str) -> bytes:
    """Escape PDF literal strings after conversion to printable ASCII."""

    cleaned = ascii_text(text)
    return cleaned.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)").encode("ascii")


def _content_stream(title: str, lines: list[str], page_number: int, page_count: int) -> bytes:
    stream = bytearray(b"BT\n")
    stream.extend(f"/F1 {TITLE_SIZE} Tf 1 0 0 1 {MARGIN_X} {PAGE_HEIGHT - MARGIN_Y} Tm\n".encode())
    stream.extend(b"(" + escape_pdf_text(title) + b") Tj\n")
    stream.extend(f"/F1 {BODY_SIZE} Tf 0 -30 Td {BODY_LEADING} TL\n".encode())
    for line in lines:
        stream.extend(b"(" + escape_pdf_text(line) + b") Tj T*\n")
    stream.extend(b"ET\n")
    footer = f"Page {page_number} of {page_count}"
    stream.extend(
        f"BT /F1 8 Tf 1 0 0 1 {MARGIN_X} 28 Tm (".encode()
        + escape_pdf_text(footer)
        + b") Tj ET\n"
    )
    return bytes(stream)


def build_pdf(title: str, body: str) -> bytes:
    """Build deterministic PDF bytes with a valid xref and page tree."""

    all_lines: list[str] = []
    for line in body.splitlines() or [""]:
        all_lines.extend(wrap_text(line))
    pages = [all_lines[index:index + LINES_PER_PAGE] for index in range(0, len(all_lines), LINES_PER_PAGE)]
    if not pages:
        pages = [[]]
    page_count = len(pages)

    # Object numbering is fixed: 1 catalog, 2 pages, 3 font, 4 info,
    # then a page/content pair for each page.
    objects: dict[int, bytes] = {
        1: b"<< /Type /Catalog /Pages 2 0 R >>",
        3: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
        4: (
            b"<< /Title (" + escape_pdf_text(title) + b") "
            b"/Producer (PropFlow Documents) /CreationDate (" + PDF_CREATION_DATE.encode() + b") >>"
        ),
    }
    kids = []
    for index, page_lines in enumerate(pages):
        page_id = 5 + index * 2
        content_id = page_id + 1
        kids.append(f"{page_id} 0 R")
        objects[page_id] = (
            f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {PAGE_WIDTH} {PAGE_HEIGHT}] "
            f"/Resources << /Font << /F1 3 0 R >> >> /Contents {content_id} 0 R >>"
        ).encode()
        content = _content_stream(title, page_lines, index + 1, page_count)
        objects[content_id] = (
            f"<< /Length {len(content)} >>\nstream\n".encode()
            + content
            + b"endstream"
        )
    objects[2] = f"<< /Type /Pages /Kids [{' '.join(kids)}] /Count {page_count} >>".encode()

    output = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = [0]
    for object_id in range(1, max(objects) + 1):
        offsets.append(len(output))
        output.extend(f"{object_id} 0 obj\n".encode())
        output.extend(objects[object_id])
        output.extend(b"\nendobj\n")
    xref_offset = len(output)
    output.extend(f"xref\n0 {len(offsets)}\n".encode())
    output.extend(b"0000000000 65535 f \n")
    for offset in offsets[1:]:
        output.extend(f"{offset:010d} 00000 n \n".encode())
    output.extend(
        f"trailer\n<< /Size {len(offsets)} /Root 1 0 R /Info 4 0 R >>\n"
        f"startxref\n{xref_offset}\n%%EOF\n".encode()
    )
    return bytes(output)


def build_document_pdf(*, title: str, subject: str, body: str) -> bytes:
    """Render a template subject/body as the document's printable content."""

    return build_pdf(title, f"{subject}\n\n{body}")
